"""Builds passages.jsonl: references into data/ (never embeds book text) + hand-written headers and gold diffs."""
import json, pathlib
P = []
def add(pid, src, a, b, header, facts, inventory=(), injuries=(), relationships=()):
    P.append(dict(id=pid, src=src, lines=[a, b], header=header,
                  gold=dict(facts=[dict(text=t, where=w, witnesses=wi, notability=n) for t, w, wi, n in facts],
                            inventory=[dict(who=x, item=i, change=c) for x, i, c in inventory],
                            injuries=[dict(who=x, desc=d) for x, d in injuries],
                            relationships=[dict(a=x, b=y, delta=d) for x, y, d in relationships])))
